(()=>{
 const modules={1:{title:'Introdução ao programa',intro:'Conheça a proposta do programa e como o acompanhamento pode apoiar mudanças de hábitos ao longo de 12 meses.',topics:['Objetivos do programa e estrutura dos encontros','Alimentação, atividade física e acompanhamento de hábitos','Apoio em grupo e definição de metas pessoais'],tips:['Conheça o calendário da turma e combine sua participação.','Registre seu ponto de partida para acompanhar mudanças.'],reflection:'Que mudança você gostaria de construir ao longo do programa?'},...window.DPP_MODULES};
 const list=document.getElementById('inline-modules');if(!list)return;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 Object.entries(modules).forEach(([id,m])=>{const num=Number(id),detail=document.createElement('details');detail.className='dpp-inline-module';detail.id='modulo-'+id;detail.dataset.phase=num<=16?'first':'second';detail.innerHTML='<summary><span class="module-number">'+id.padStart(2,'0')+'</span><span class="module-name">'+esc(m.title)+'</span></summary><div class="dpp-module-body"><p>'+esc(m.intro)+'</p><h4>Conteúdo</h4><ul>'+m.topics.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul><h4>Para praticar</h4><ul>'+m.tips.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul><p><strong>Reflexão:</strong> '+esc(m.reflection)+'</p><p class="chart-scope">Resumo de apoio à leitura. O material original em português reúne os arquivos do participante e do facilitador.</p><a href="https://coveragetoolkit.org/wp-content/uploads/2022/02/Portuguese-Curriculum-Module-'+id+'.zip" download>Baixar material original do módulo (ZIP) ↓</a></div>';list.append(detail);});
 const buttons=[...document.querySelectorAll('[data-phase]')].filter(x=>x.tagName==='BUTTON');buttons.forEach(button=>button.addEventListener('click',()=>{const phase=button.dataset.phase;buttons.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;list.querySelectorAll('.dpp-inline-module').forEach(d=>{d.hidden=phase!=='all'&&d.dataset.phase!==phase;if(!d.hidden)count++;});document.getElementById('dpp-module-count').textContent=count+' módulos';}));
})();
